mapper.select:
select 
from knowledge_submissions
where id = #{id}
  and school_id = #{schoolId}
limit 1

mapper.update:
update knowledge_submissions
set status = 'APPROVED',
    review_note = #{reviewNote},
    reviewed_by = #{reviewedBy},
    reviewed_at = current_timestamp,
    knowledge_document_id = #{knowledgeDocumentId}
where id = #{id}
  and school_id = #{schoolId}
  and status = 'PENDING'
